use lito_modern::modern_lito::{native_resources as r,world_map::{WorldMap,SectorInput},resources::SharedMapSectorKey,scene::CameraRect};
use serde_json::{Value,json};use sha2::{Digest,Sha256};use anyhow::{Result,Context,ensure};use std::{path::Path,sync::atomic::AtomicBool,fs};
fn bp(v:&Value)->Result<r::BytePin>{let h=v["sha256"].as_str().context("sha")?;let mut sha256=[0;32];for(i,b)in sha256.iter_mut().enumerate(){*b=u8::from_str_radix(&h[2*i..2*i+2],16)?;}Ok(r::BytePin{bytes:v["bytes"].as_u64().context("bytes")?,sha256})}
fn main()->Result<()>{let args:Vec<_>=std::env::args_os().collect();ensure!(args.len()==3,"probe input/output paths required");let m:Value=serde_json::from_slice(&fs::read(&args[1])?)?;let id=m["map_id"].as_u64().unwrap() as u32;let key=SharedMapSectorKey{map_id:id,sector_x:m["sector_x"].as_u64().unwrap() as u16,sector_y:m["sector_y"].as_u64().unwrap() as u16};let raw=fs::read(m["sector"]["path"].as_str().unwrap())?;ensure!(<[u8;32]>::from(Sha256::digest(&raw))==bp(&m["sector"])?.sha256,"probe sector drift");let cancel=AtomicBool::new(false);let world=WorldMap::from_sector_bytes(vec![SectorInput{key,bytes:raw}],&cancel)?;let canonical=world.canonical_digest();let plan=r::NativeAssetPlan{namespace:r::ResourceNamespace::NativeLitoV1,map_id:id,canonical_sha256:canonical,sectors:vec![r::SectorPin{key:r::NativeSectorKey{map_id:id,x:key.sector_x,y:key.sector_y},pin:bp(&m["sector"])?}],archives:m["archives"].as_array().unwrap().iter().zip([r::ArchiveRole::TileIndex,r::ArchiveRole::TilePak,r::ArchiveRole::SpriteIndex,r::ArchiveRole::SpritePak]).map(|(v,role)|Ok(r::ArchivePin{role,pin:bp(v)?})).collect::<Result<_>>()?};let sources=r::NativeSources{map_root:m["map_root"].as_str().unwrap().into(),archive_root:m["archive_root"].as_str().unwrap().into()};let assets=r::NativeResourceAdapter::pinned_inspection().load_static(&sources,&plan,Default::default(),&cancel)?;let c=assets.render_static(CameraRect{x:1136,y:468,width:800,height:600},&cancel)?;let output=Path::new(&args[2]);let image=output.with_extension("png");let mut e=png::Encoder::new(fs::File::create(&image)?,800,600);e.set_color(png::ColorType::Rgba);e.set_depth(png::BitDepth::Eight);e.write_header()?.write_image_data(c.rgba())?;let bytes=fs::read(&image)?;let visible=c.rgba().chunks_exact(4).filter(|p|p[..3]!=[0,0,0]).count();ensure!(visible>10000,"actual second map reference is not informative");let out=json!({"state":"FIXED_R476_LIBRARY_ACTUAL_NATIVE514_RESOURCES_CANONICAL_AND_CPU_REFERENCE","map_id":id,"mode":1,"canonical_sha256":format!("{:X}",Sha256::digest(world.canonical_bytes())),"canonical_digest":canonical.iter().map(|b|format!("{b:02X}")).collect::<String>(),"image":{"path":image,"bytes":bytes.len(),"sha256":format!("{:X}",Sha256::digest(&bytes)),"rgba_sha256":format!("{:X}",Sha256::digest(c.rgba()))},"nonblack_pixels":visible,"Native_sector_and_four_archives_verified":true,"GUI":0});fs::write(output,serde_json::to_vec_pretty(&out)?)?;println!("Native{id} canonical/render PASS pixels{visible}");Ok(())}
